def _response_field(field: str, child: str) -> str:
    return f"{field}.{child}" if field else child


def _response_index(field: str, index: int) -> str:
    return f"{field}[{index}]"


def _enum_matches(value: object, candidate: object) -> bool:
    if isinstance(value, bool) or isinstance(candidate, bool):
        return type(value) is type(candidate) and value == candidate
    if isinstance(value, (int, float)) and isinstance(candidate, (int, float)):
        return value == candidate
    return type(value) is type(candidate) and value == candidate


def _validate_response_enum_node(
    value: object,
    schema: object,
    field: str,
    active: set[tuple[int, int]],
) -> None:
    if not isinstance(schema, dict) or value is None:
        return
    reference = schema.get("ref")
    if isinstance(reference, str):
        target = _RESPONSE_ENUM_SCHEMAS.get(reference)
        if target is not None:
            _validate_response_enum_node(value, target, field, active)
        return

    visit = (id(value), id(schema))
    if visit in active:
        return
    active = {*active, visit}

    for member in schema.get("allOf", ()):
        _validate_response_enum_node(value, member, field, active)

    union = schema.get("oneOf") or schema.get("anyOf")
    open_tag = schema.get("openTag")
    if isinstance(open_tag, list) and isinstance(value, dict):
        tag = value.get(open_tag[0])
        if isinstance(tag, str) and tag not in open_tag[1]:
            # A member whose tag names no branch is kept as received.
            return
    if isinstance(union, list) and union:
        rejection: SdkValidationError | None = None
        for member in union:
            try:
                _validate_response_enum_node(value, member, field, active)
            except SdkValidationError as error:
                rejection = rejection or error
            else:
                return
        if rejection is not None:
            raise rejection

    properties = schema.get("properties")
    if isinstance(value, dict) and isinstance(properties, dict):
        for name, child_schema in properties.items():
            if name in value:
                _validate_response_enum_node(
                    value[name], child_schema, _response_field(field, name), active
                )

    additional = schema.get("additionalProperties")
    if isinstance(value, dict) and additional is not None:
        known = set(properties) if isinstance(properties, dict) else set()
        for name, child in value.items():
            if name not in known:
                _validate_response_enum_node(
                    child, additional, _response_field(field, name), active
                )

    items = schema.get("items")
    if isinstance(value, list) and items is not None:
        for index, child in enumerate(value):
            _validate_response_enum_node(child, items, _response_index(field, index), active)

    allowed = schema.get("enum")
    if isinstance(allowed, list) and not any(
        _enum_matches(value, candidate) for candidate in allowed
    ):
        raise SdkValidationError(
            field,
            "enum",
            f"Validation failed for '{field}': must be one of {allowed}",
            {"allowed": allowed},
        )


def _validate_response_enums(value: object, type_name: str, field: str = "") -> object:
    """Validates strict response enums against raw wire-shaped payload data.
    A list and a `map:<Model>` type are read the way `from_wire` reads them."""
    if isinstance(value, list):
        for index, item in enumerate(value):
            _validate_response_enums(item, type_name, _response_index(field, index))
    elif type_name.startswith("map:") and isinstance(value, dict):
        for key, item in value.items():
            _validate_response_enums(item, type_name[4:], _response_field(field, key))
    else:
        _validate_response_enum_node(value, {"ref": type_name}, field, set())
    return value


def _plain_to_wire(value: Any) -> Any:
    if value is NOT_GIVEN:
        return NOT_GIVEN
    if isinstance(value, (datetime.datetime, datetime.date, datetime.time)):
        return _wire_scalar(value)
    if isinstance(value, Enum):
        return value.value
    if is_dataclass(value) and not isinstance(value, type):
        model_name = type(value).__name__
        if model_name in _WIRE_SCHEMAS:
            return to_wire(value, model_name)
        return {
            field.name: _plain_to_wire(getattr(value, field.name))
            for field in fields(value)
            if getattr(value, field.name) is not NOT_GIVEN
        }
    model_dump = getattr(value, "model_dump", None)
    if callable(model_dump):
        return _plain_to_wire(model_dump(by_alias=True, exclude_unset=True))
    if isinstance(value, dict):
        return {key: _plain_to_wire(item) for key, item in value.items() if item is not NOT_GIVEN}
    if isinstance(value, (list, tuple)):
        return [_plain_to_wire(item) for item in value]
    return value


def _to_wire_nested(value: Any, nested: str | None) -> Any:
    if nested is None:
        return _plain_to_wire(value)
    if isinstance(value, (list, tuple)):
        return [_to_wire_nested(item, nested) for item in value]
    if nested.startswith("map:"):
        value_type = nested[4:]
        return {key: _to_wire_nested(item, value_type) for key, item in value.items()}
    if nested.startswith("union:"):
        members = nested[6:].partition("~")[0].split("|")
        for member in members:
            cls = _WIRE_SCHEMAS[member][0]
            if cls is not None and isinstance(value, cls):
                return to_wire(value, member)
        if isinstance(value, dict):
            value_keys = set(value)
            member = max(
                members,
                key=lambda name: len(
                    value_keys
                    & (
                        set(_WIRE_SCHEMAS[name][1])
                        | {wire for wire, _nested in _WIRE_SCHEMAS[name][1].values()}
                    )
                ),
            )
            return to_wire(value, member)
        return _plain_to_wire(value)
    return to_wire(value, nested)


def to_wire(value: Any, type_name: str) -> Any:
    """Rewrites a payload's keys from idiomatic names to the spec's wire names,
    recursing into nested models and lists."""
    type_name = _WIRE_LIST_ALIASES.get(type_name, type_name)
    entry = _WIRE_SCHEMAS.get(type_name)
    if value is None or entry is None:
        return _plain_to_wire(value)
    if isinstance(value, list):
        return [to_wire(item, type_name) for item in value]
    _cls, schema = entry
    out: dict[str, Any] = {}
    for attr, (wire, nested) in schema.items():
        if isinstance(value, dict):
            # Accept values keyed by the idiomatic name or already by the wire
            # name, so callers may pass model instances or wire-shaped dicts.
            raw = value[attr] if attr in value else value.get(wire, _MISSING)
        else:
            raw = getattr(value, attr, _MISSING)
        if raw is _MISSING or raw is NOT_GIVEN:
            continue
        out[wire] = _to_wire_nested(raw, nested)
    # Keys the model does not declare, an open model's extras, go out as given.
    extras = (
        value
        if isinstance(value, dict)
        else getattr(value, "model_extra", None)
        or getattr(value, "additional_properties", None)
        or {}
    )
    for key, raw in extras.items():
        if key not in schema and key not in out and raw is not NOT_GIVEN:
            out[key] = _plain_to_wire(raw)
    return out
